mapper.select:
/* Attd12Mapper.selectScopedAttdRows */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD , U.USER_ID , U.USER_NM , NT.NODE_NM FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL )
SELECT A.WORK_YMD AS workYmd , U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.NODE_NM AS nodeNm , S.SITE_NM AS siteNm , A.CHECK_IN_TIME AS checkInTime , A.CHECK_OUT_TIME AS checkOutTime , A.CHECK_IN_DEVICE_UUID AS checkInDeviceUuid , A.CHECK_OUT_DEVICE_UUID AS checkOutDeviceUuid FROM target_user U INNER JOIN TB_USER_ATTD_MGMT A ON A.CMPNY_CD = U.CMPNY_CD AND A.SITE_CD = U.SITE_CD AND A.USER_CD = U.USER_CD AND A.DEL_YN = 'N' AND A.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%') INNER JOIN TB_SITE S ON S.CMPNY_CD = A.CMPNY_CD AND S.SITE_CD = A.SITE_CD ORDER BY A.WORK_YMD, A.CHECK_IN_DEVICE_UUID, U.USER_CD, A.CHECK_IN_TIME

/* Attd12Mapper.selectUserDeviceBaseline */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
target_user AS ( SELECT U.CMPNY_CD , U.USER_CD FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL )
SELECT DISTINCT H.USER_CD AS userCd , H.DEVICE_UUID AS deviceUuid FROM TB_USER_DEVICE_LOGIN_HIST H INNER JOIN target_user U ON H.CMPNY_CD = U.CMPNY_CD AND H.USER_CD = U.USER_CD WHERE H.CMPNY_CD = #{gvCmpnyCd}
